import { defineConfig } from "vite";
import { fileURLToPath } from "url";
import path from "path";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const ENTRY_FILE_NAME = path.resolve(__dirname, "resource/ts/app.ts");
const OUT_DIR = path.resolve(__dirname, "resource/dist/js");
function createManualChunk(id: string): string | undefined {
  if (!id.includes("node_modules")) {
    return undefined;
  }

  if (id.includes("@theatre/studio")) {
    return "theatre-studio";
  }

  if (id.includes("@theatre/core")) {
    return "theatre-core";
  }

  if (id.includes("three")) {
    return "three-vendor";
  }

  return "vendor";
}

export default defineConfig(({ mode }) => {
  const isProd = mode === "production";
  return {
    root: __dirname,
    base: "/resource/dist/js/",
    build: {
      target: "es2020",
      modulePreload: false,
      outDir: OUT_DIR,
      emptyOutDir: true,
      manifest: false,
      sourcemap: !isProd,
      minify: isProd ? "esbuild" : false,
      cssCodeSplit: false,
      chunkSizeWarningLimit: 1000,
      rollupOptions: {
        preserveEntrySignatures: "strict",
        input: {
          app: ENTRY_FILE_NAME,
        },
        output: {
          entryFileNames: "app.js",
          chunkFileNames: "chunks/[name]-[hash].js",
          manualChunks: createManualChunk,
          assetFileNames: (assetInfo) => {
            const name = assetInfo.name ?? "";
            if (/\.(woff2?|ttf|otf|eot)$/.test(name)) {
              return "fonts/[name]-[hash][extname]";
            }
            return "assets/[name]-[hash][extname]";
          },
        },
      },
    },
  };
});

include_once $autoloadPath;

if (!function_exists('no_render_internal_error')) {
    function no_render_internal_error(string $message = 'Internal Server Error', int $statusCode = 500): void
    {
        ErrorHandler::renderError($message, $statusCode);
    }
}

$isDevelopmentEnv = defined('ENV') && defined('ENV_DEVELOPMENT') && ENV === ENV_DEVELOPMENT;
no_bootstrap_error_reporting($isDevelopmentEnv);

